# Generated by build.py from recipe.yml for recipe https-refuse-clients-below-tls-1-3. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--cert', 'server.pem', '--key', 'server.key', '--tlsv1.3', 'https://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --tlsv1.3 --cacert server.pem https://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
